\begin{aligned}
\mathsf{TypeJud}_{\mathsf S}&=\{\Gamma\vdash A\ \mathsf{type}:\Gamma\in\mathsf{Ctx}_{\mathsf S},A\in\mathsf{Ty}_{\mathsf S}\},\\
\mathsf{TmJud}_{\mathsf S}&=\{\Gamma\vdash t:A:\Gamma\in\mathsf{Ctx}_{\mathsf S},t\in\mathsf{Tm}_{\mathsf S},A\in\mathsf{Ty}_{\mathsf S}\},\\
\mathsf{EqJud}_{\mathsf S}&=\{\Gamma\vdash a\approx_A b:\Gamma\in\mathsf{Ctx}_{\mathsf S},a,b\in\mathsf{Tm}_{\mathsf S},A\in\mathsf{Ty}_{\mathsf S}\},\\
\mathsf{Jud}_{\mathsf S}&=\mathsf{TypeJud}_{\mathsf S}\cup\mathsf{TmJud}_{\mathsf S}\cup\mathsf{EqJud}_{\mathsf S}.
\end{aligned}

\mathsf{Der}_{\mathsf S}
=\{(P,\ell):P\in\mathsf{TreeDom}_{\mathsf S},\ \ell:P\to\mathsf{Jud}_{\mathsf S},\
\forall p\in P\ ((\langle\ell(q):q\in\operatorname{ch}_P(p)\rangle,\ell(p))\in\mathsf{Rule}_{\mathsf S})\}.
